#include <deque>
#include <memory>

// Demonstrates safe insertion of copyable type
int main() {
    std::shared_ptr<int> p_source(new int(10));
    std::deque<std::shared_ptr<int>> d;

    // Safe copy: p_source remains valid
    d.push_back(p_source);

    // p_source still points to 10
    if (p_source && *p_source == 10) {
        // OK
    }

    // DANGER: If p_source were std::auto_ptr, it would now be null 
    // and the container would hold the sole valid pointer.
}
